/* ============================================================
   PATCH 1.0.20 (v2) — пересчёт подсказки после установки умолчания
   НЕ оборачивает _applyDefaultHours (observer 1.0.19 её не вызывает через window).
   Вместо этого — независимый observer на 500/900мс (после 1.0.19 30/150/400мс).
   ============================================================ */
(function(){
'use strict';
if (window.__trkHoursSyncV1020b) return;
window.__trkHoursSyncV1020b = true;

function _syncSummary() {
    var lh = document.getElementById('log_hours');
    if (!lh) return;
    // Не трогаем при редактировании
    var lid = document.getElementById('log_id');
    if (lid && lid.value) return;
    // Не трогаем, если пользователь ввёл сам
    if (lh._userTouchedHours) return;
    // Диспатчим input — updateDayHoursSummary пересчитает planned
    try {
        lh.dispatchEvent(new Event('input', { bubbles: true }));
    } catch (e) {}
    // 1.0.19 ставит _userTouchedHours = true на каждый input (в т.ч. программный).
    // Сбрасываем, чтобы следующая смена даты / открытие снова пересчитало.
    lh._userTouchedHours = false;
}

(function _watchOpen(){
    var lm = document.getElementById('logModal');
    if (!lm || lm._hoursSyncV1020b) return;
    lm._hoursSyncV1020b = true;
    new MutationObserver(function(){
        if (lm.classList.contains('active')) {
            // Сброс флага при открытии (1.0.19 тоже сбрасывает, но на случай его отсутствия)
            var lh0 = document.getElementById('log_hours');
            if (lh0) lh0._userTouchedHours = false;
            // 1.0.19: 30/150/400мс. Мы: 500/900мс — после него.
            setTimeout(_syncSummary, 500);
            setTimeout(_syncSummary, 900);
        }
    }).observe(lm, { attributes: true, attributeFilter: ['class'] });
})();

document.addEventListener('change', function(e){
    if (!e.target || e.target.id !== 'log_date') return;
    setTimeout(_syncSummary, 200);
    setTimeout(_syncSummary, 500);
}, true);

setTimeout(_syncSummary, 1200);

})();
